      normalizedLabels[key] = value;
    }
    normalized.labels = normalizedLabels;
  }

  return normalized;
}

export async function callTool(name, args = {}) {
  if (name !== 'profile_patch') {
    throw fail(`Unknown tool: ${name}`, -32601);
  }

